const IMAGE_TYPES = ['image/jpeg','image/png','image/webp'];

export function usePrivateImage(path?: string | null,bucket='hka-private') {
  const [url,setUrl]=useState('');
  useEffect(()=>{let active=true;setUrl('');if(!path)return;void db().storage.from(bucket).createSignedUrl(path,3600).then(({data})=>{if(active)setUrl(data?.signedUrl??'');});return()=>{active=false;};},[path,bucket]);
  return url;
}

export function PrivatePhoto({path,label,horse=false,className='size-24',bucket='hka-private'}:{path?:string|null;label:string;horse?:boolean;className?:string;bucket?:string}){
  const url=usePrivateImage(path,bucket);
  return <Avatar className={className+' border-2 border-[#B79B62]/60 bg-[#f7f3e9] shadow-sm'}><AvatarImage src={url} alt={label} className='object-cover'/><AvatarFallback className='bg-[#ece5d6] text-primary'>{horse?<HorseshoeIcon className='size-1/2'/>:<UserRound className='size-1/2'/>}</AvatarFallback></Avatar>;
}

export function CircularPhotoEditor({path,label,horse=false,bucket='hka-private',onSave,onRemove,className='size-28'}:{path?:string|null;label:string;horse?:boolean;bucket?:string;onSave:(file:File)=>Promise<void>;onRemove?:()=>Promise<void>;className?:string}){
  const [open,setOpen]=useState(false);const [viewOpen,setViewOpen]=useState(false);const [source,setSource]=useState('');const currentUrl=usePrivateImage(path,bucket);const [zoom,setZoom]=useState(1);const [offset,setOffset]=useState({x:0,y:0});const [natural,setNatural]=useState({width:1,height:1});const [busy,setBusy]=useState(false);const drag=useRef<{x:number;y:number;ox:number;oy:number}|null>(null);
  useEffect(()=>()=>{if(source)URL.revokeObjectURL(source);},[source]);
  function choose(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!IMAGE_TYPES.includes(file.type)||file.size>5242880){window.alert('Choose a JPG, PNG or WebP image up to 5 MB.');return;}if(source)URL.revokeObjectURL(source);setSource(URL.createObjectURL(file));setZoom(1);setOffset({x:0,y:0});setOpen(true);}
  const base=Math.max(280/natural.width,280/natural.height);const clamp=(x:number,y:number,z=zoom)=>({x:Math.max(-(natural.width*base*z-280)/2,Math.min((natural.width*base*z-280)/2,x)),y:Math.max(-(natural.height*base*z-280)/2,Math.min((natural.height*base*z-280)/2,y))});
  function pointerDown(event:ReactPointerEvent<HTMLDivElement>){event.currentTarget.setPointerCapture(event.pointerId);drag.current={x:event.clientX,y:event.clientY,ox:offset.x,oy:offset.y};}
  function pointerMove(event:ReactPointerEvent<HTMLDivElement>){if(!drag.current)return;setOffset(clamp(drag.current.ox+event.clientX-drag.current.x,drag.current.oy+event.clientY-drag.current.y));}
  async function save(){const image=new Image();image.src=source;await image.decode();const scale=base*zoom;const side=280/scale;const sx=image.naturalWidth/2-side/2-offset.x/scale;const sy=image.naturalHeight/2-side/2-offset.y/scale;const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;canvas.getContext('2d')?.drawImage(image,sx,sy,side,side,0,0,512,512);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('Photo could not be prepared.')),'image/jpeg',0.92));setBusy(true);try{await onSave(new File([blob],'cropped-photo.jpg',{type:'image/jpeg'}));setOpen(false);}finally{setBusy(false);}}
  return <div className='flex flex-col items-center gap-3 sm:items-start'><details className='group relative'><summary className='cursor-pointer list-none rounded-full outline-none ring-offset-2 focus-visible:ring-2 focus-visible:ring-[#B79B62]' aria-label={'Open photo options for '+label}><PrivatePhoto path={path} label={label} horse={horse} className={className} bucket={bucket}/></summary><div className='absolute left-1/2 top-[calc(100%+0.5rem)] z-40 w-44 -translate-x-1/2 overflow-hidden rounded-lg border border-primary/15 bg-[#fffdf8] py-1 shadow-xl sm:left-0 sm:translate-x-0'>{path&&<button type='button' className='flex min-h-10 w-full items-center gap-2 px-3 text-left text-xs hover:bg-primary/5' onClick={()=>setViewOpen(true)}><Eye className='size-4'/>View photo</button>}<label className='flex min-h-10 cursor-pointer items-center gap-2 px-3 text-xs hover:bg-primary/5'><Upload className='size-4'/>{path?'Change photo':'Upload photo'}<input className='sr-only' type='file' accept='image/jpeg,image/png,image/webp' onChange={choose}/></label>{path&&onRemove&&<button type='button' className='flex min-h-10 w-full items-center gap-2 px-3 text-left text-xs text-destructive hover:bg-destructive/5' onClick={()=>{if(window.confirm('Remove this photo?'))void onRemove();}}><Trash2 className='size-4'/>Remove photo</button>}</div></details><Dialog open={viewOpen} onOpenChange={setViewOpen}><DialogContent className='max-w-lg'><DialogHeader><DialogTitle>{label}</DialogTitle><DialogDescription>Private profile photograph.</DialogDescription></DialogHeader><div className='aspect-square overflow-hidden rounded-lg bg-[#e9e2d3]'>{currentUrl?<img src={currentUrl} alt={label} className='size-full object-cover'/>:<div className='grid size-full place-items-center text-muted-foreground'><UserRound className='size-20'/></div>}</div></DialogContent></Dialog><Dialog open={open} onOpenChange={value=>{if(!busy)setOpen(value);}}><DialogContent className='max-w-md'><DialogHeader><DialogTitle>Position your photo</DialogTitle><DialogDescription>Drag to reposition and use zoom. Original colours and appearance stay unchanged.</DialogDescription></DialogHeader><div className='mx-auto size-[280px] touch-none overflow-hidden rounded-full border-4 border-[#B79B62] bg-[#e9e2d3] shadow-inner' onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={()=>{drag.current=null;}} onPointerCancel={()=>{drag.current=null;}}>{source&&<img src={source} alt='Crop preview' draggable={false} onLoad={event=>setNatural({width:event.currentTarget.naturalWidth,height:event.currentTarget.naturalHeight})} className='pointer-events-none relative left-1/2 top-1/2 max-w-none select-none' style={{width:natural.width*base*zoom,height:natural.height*base*zoom,transform:'translate(calc(-50% + '+offset.x+'px), calc(-50% + '+offset.y+'px))'}}/>}</div><label className='flex items-center gap-3 text-sm'><ZoomIn className='size-4'/><span>Zoom</span><input className='w-full accent-[#304b3f]' aria-label='Photo zoom' type='range' min='1' max='3' step='0.01' value={zoom} onChange={event=>{const next=Number(event.target.value);setZoom(next);setOffset(current=>clamp(current.x,current.y,next));}}/></label><DialogFooter><Button type='button' variant='outline' onClick={()=>setOpen(false)} disabled={busy}>Cancel</Button><Button type='button' onClick={()=>void save()} disabled={busy||!source}>{busy?'Saving…':'Save photo'}</Button></DialogFooter></DialogContent></Dialog></div>;
}

export async function uploadProfilePhoto(userId:string,file:File){if(file.type!=='image/jpeg'||file.size<=0||file.size>5242880)throw new Error('Choose a JPEG profile photograph up to 5 MB.');const {data:current}=await db().from('hka_profiles').select('avatar_path').eq('id',userId).single();const previous=typeof current?.avatar_path==='string'?current.avatar_path:null;const id=crypto.randomUUID();const path=userId+'/'+id+'.jpg';const {error:meta}=await db().from('hka_files').insert({id,owner_id:userId,path,original_name:file.name,purpose:'avatar',mime_type:file.type,size_bytes:file.size,student_id:userId});if(meta)throw meta;const {error:upload}=await db().storage.from('hka-avatars').upload(path,file,{contentType:file.type,upsert:false});if(upload){await db().from('hka_files').delete().eq('id',id);throw upload;}const {error:update}=await db().from('hka_profiles').update({avatar_path:path}).eq('id',userId);if(update){await db().storage.from('hka-avatars').remove([path]);await db().from('hka_files').delete().eq('id',id);throw update;}if(previous){await db().storage.from('hka-avatars').remove([previous]);await db().from('hka_files').delete().eq('path',previous);}return path;}

export async function removeProfilePhoto(userId:string,path?:string|null){const {error}=await db().from('hka_profiles').update({avatar_path:null}).eq('id',userId);if(error)throw error;if(path){await db().storage.from('hka-avatars').remove([path]);await db().from('hka_files').delete().eq('path',path);}}

export function SelfAvatarEditor({className='size-24'}:{className?:string}){const {profile,refreshProfile}=useSession();const [message,setMessage]=useState('');if(!profile)return null;async function save(file:File){await uploadProfilePhoto(profile!.id,file);await refreshProfile();setMessage('Photo saved.');}async function remove(){await removeProfilePhoto(profile!.id,profile!.avatar_path);await refreshProfile();setMessage('Photo removed.');}return <div><CircularPhotoEditor path={profile.avatar_path} label={profile.full_name||'Profile photo'} bucket='hka-avatars' className={className} onSave={save} onRemove={remove}/>{message&&<span className='sr-only' role='status'>{message}</span>}</div>;}

function personalGreeting(name:string,timezone:string){let hour=new Date().getHours();try{hour=Number(new Intl.DateTimeFormat('en-GB',{hour:'2-digit',hour12:false,timeZone:timezone}).format(new Date()));}catch{hour=new Date().getHours();}const salutation=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';return salutation+', '+(name.trim().split(/\s+/)[0]||'rider')+'.';} export function DashboardHero({label,defaultSubtitle,actions}:{label:string;defaultSubtitle:string;actions?:ReactNode}){const {profile,refreshProfile}=useSession();const bannerUrl=usePrivateImage(profile?.banner_path,'hka-banners');const [open,setOpen]=useState(false);const [source,setSource]=useState('');const [subtitle,setSubtitle]=useState(profile?.banner_subtitle||defaultSubtitle);const [focusX,setFocusX]=useState(50);const [focusY,setFocusY]=useState(50);const [zoom,setZoom]=useState(1);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');useEffect(()=>{setSubtitle(profile?.banner_subtitle||defaultSubtitle);},[profile?.banner_subtitle,defaultSubtitle]);useEffect(()=>()=>{if(source)URL.revokeObjectURL(source);},[source]);function choose(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!IMAGE_TYPES.includes(file.type)||file.size<=0||file.size>8388608){setMessage('Choose a JPG, PNG or WebP photograph up to 8 MB.');return;}if(source)URL.revokeObjectURL(source);setSource(URL.createObjectURL(file));setFocusX(50);setFocusY(50);setZoom(1);}async function save(){if(!profile)return;setBusy(true);setMessage('');try{let nextPath=profile.banner_path??null;let uploadedPath:string|null=null;if(source){const image=new Image();image.src=source;await image.decode();const ratio=8/3;let cropWidth=image.naturalWidth;let cropHeight=cropWidth/ratio;if(cropHeight>image.naturalHeight){cropHeight=image.naturalHeight;cropWidth=cropHeight*ratio;}cropWidth/=zoom;cropHeight/=zoom;const sx=(image.naturalWidth-cropWidth)*(focusX/100);const sy=(image.naturalHeight-cropHeight)*(focusY/100);const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=600;canvas.getContext('2d')?.drawImage(image,sx,sy,cropWidth,cropHeight,0,0,1600,600);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('Banner could not be prepared.')),'image/jpeg',0.9));nextPath=profile.id+'/dashboard-banner-'+crypto.randomUUID()+'.jpg';uploadedPath=nextPath;const {error:upload}=await db().storage.from('hka-banners').upload(nextPath,blob,{contentType:'image/jpeg',upsert:true});if(upload)throw upload;}const clean=subtitle.trim().slice(0,140);const {data:saved,error}=await db().from('hka_profiles').update({banner_path:nextPath,banner_subtitle:clean||null}).eq('id',profile.id).select('banner_path,banner_subtitle').single();if(error){if(uploadedPath)await db().storage.from('hka-banners').remove([uploadedPath]);throw error;}if(saved?.banner_path!==nextPath||(saved?.banner_subtitle??'')!==(clean||''))throw new Error('Banner could not be confirmed. Please retry.');if(profile.banner_path&&profile.banner_path!==nextPath)await db().storage.from('hka-banners').remove([profile.banner_path]);await refreshProfile();setSource('');setOpen(false);setMessage('Banner saved.');}catch(error){setMessage(errorText(error));}finally{setBusy(false);}}async function restore(){if(!profile)return;setBusy(true);setMessage('');try{const previousPath=profile.banner_path;const {data:saved,error}=await db().from('hka_profiles').update({banner_path:null,banner_subtitle:null}).eq('id',profile.id).select('banner_path,banner_subtitle').single();if(error)throw error;if(saved?.banner_path!==null||saved?.banner_subtitle!==null)throw new Error('Default banner could not be confirmed. Please retry.');if(previousPath)await db().storage.from('hka-banners').remove([previousPath]);setSource('');setSubtitle(defaultSubtitle);await refreshProfile();setOpen(false);setMessage('Default HKA banner restored.');}catch(error){setMessage(errorText(error));}finally{setBusy(false);}}const position=focusX+'% '+focusY+'%';return <section className='dashboard-hero dashboard-personal-banner relative overflow-hidden p-5 sm:p-7'>{bannerUrl&&<img src={bannerUrl} alt='' className='absolute inset-0 size-full object-cover'/>}<div className={bannerUrl?'absolute inset-0 bg-gradient-to-r from-[#102f27]/95 via-[#17392f]/80 to-[#17392f]/25':'absolute inset-0 bg-gradient-to-br from-[#f8f4e9] to-[#efe6d4]'}/><div className='relative flex flex-col justify-between gap-5 lg:flex-row lg:items-end'><div className='flex flex-col gap-5 sm:flex-row sm:items-center'><SelfAvatarEditor className='size-20 sm:size-24'/><div className={bannerUrl?'text-[#fffaf0]':''}><p className={'eyebrow mb-3 '+(bannerUrl?'text-[#ddc789]':'text-[#76633e]')}>{label}</p><h1 className='section-heading'>{profile?personalGreeting(profile.full_name,profile.timezone):'Welcome.'}</h1><p className={'mt-3 max-w-2xl text-sm '+(bannerUrl?'text-[#fffaf0]/85':'text-muted-foreground')}>{profile?.banner_subtitle||defaultSubtitle}</p></div></div><div className='flex flex-wrap items-center gap-2'><Button type='button' variant={bannerUrl?'secondary':'outline'} onClick={()=>{setMessage('');setOpen(true);}}><Pencil className='size-4'/>Edit banner</Button>{actions}</div></div>{message&&<p className={'relative mt-3 text-xs '+(bannerUrl?'text-[#fffaf0]':'text-muted-foreground')} role='status'>{message}</p>}<Dialog open={open} onOpenChange={value=>{if(!busy)setOpen(value);}}><DialogContent className='max-h-[90vh] max-w-3xl overflow-y-auto'><DialogHeader><DialogTitle>Edit dashboard banner</DialogTitle><DialogDescription>Upload an original photograph, position it, preview both layouts, and save it privately to your profile.</DialogDescription></DialogHeader><div className='grid gap-5'><label className='flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-primary/30 bg-primary/5 px-4 text-sm'><Upload className='size-4'/>{source?'Choose another photograph':'Upload photograph'}<input type='file' className='sr-only' accept='image/jpeg,image/png,image/webp' onChange={choose}/></label>{source&&<><div><Label>Desktop preview</Label><div className='mt-2 aspect-[8/3] overflow-hidden rounded-lg border bg-[#e9e2d3]'><img src={source} alt='Desktop banner preview' className='size-full object-cover' style={{objectPosition:position,transform:'scale('+zoom+')'}}/></div></div><div className='grid gap-4 sm:grid-cols-[1fr_13rem]'><div><Label>Mobile preview</Label><div className='mt-2 aspect-[4/3] overflow-hidden rounded-lg border bg-[#e9e2d3]'><img src={source} alt='Mobile banner preview' className='size-full object-cover' style={{objectPosition:position,transform:'scale('+zoom+')'}}/></div></div><div className='grid content-center gap-3'><label className='text-xs'>Horizontal position<input className='mt-1 w-full accent-[#304b3f]' type='range' min='0' max='100' value={focusX} onChange={event=>setFocusX(Number(event.target.value))}/></label><label className='text-xs'>Vertical position<input className='mt-1 w-full accent-[#304b3f]' type='range' min='0' max='100' value={focusY} onChange={event=>setFocusY(Number(event.target.value))}/></label><label className='text-xs'>Zoom<input className='mt-1 w-full accent-[#304b3f]' type='range' min='1' max='2.5' step='0.01' value={zoom} onChange={event=>setZoom(Number(event.target.value))}/></label></div></div></>}<div><Label htmlFor='banner-subtitle'>Personal subtitle</Label><Textarea id='banner-subtitle' value={subtitle} onChange={event=>setSubtitle(event.target.value)} maxLength={140} className='mt-2 min-h-20'/><p className='mt-1 text-right text-xs text-muted-foreground'>{subtitle.length}/140</p></div>{message&&<p className='rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive' role='alert'>{message}</p>}</div><DialogFooter className='gap-2 sm:justify-between'><Button type='button' variant='ghost' onClick={()=>void restore()} disabled={busy}><RotateCcw className='size-4'/>Restore default</Button><div className='flex gap-2'><Button type='button' variant='outline' onClick={()=>setOpen(false)} disabled={busy}>Cancel</Button><Button type='button' onClick={()=>void save()} disabled={busy}>{busy?'Saving…':'Save banner'}</Button></div></DialogFooter></DialogContent></Dialog></section>;} export function useDashboardNavigation(scope:string,allowed:string[],fallback:string){const {profile}=useSession();const location=useLocation();const navigate=useNavigate();const key='hka-dashboard:'+profile?.id+':'+scope;const requested=new URLSearchParams(location.search).get('section')||location.hash.replace('#','');const initial=allowed.includes(requested)?requested:fallback;const [current,setCurrent]=useState(allowed.includes(initial)?initial:fallback);const [trail,setTrail]=useState<string[]>([allowed.includes(initial)?initial:fallback]);const [cursor,setCursor]=useState(0);
  useEffect(()=>{const direct=new URLSearchParams(location.search).get('section')||location.hash.replace('#','');if(allowed.includes(direct)&&direct!==current){setCurrent(direct);localStorage.setItem(key,direct);setTrail(items=>items.slice(0,cursor+1).concat(direct));setCursor(value=>value+1);}else if(!direct&&current!==fallback){setCurrent(fallback);localStorage.setItem(key,fallback);}},[location.search,location.hash]);
  function select(next:string){if(next===current||!allowed.includes(next))return;const params=new URLSearchParams(location.search);if(next===fallback)params.delete('section');else params.set('section',next);setCurrent(next);localStorage.setItem(key,next);setTrail(items=>items.slice(0,cursor+1).concat(next));setCursor(value=>value+1);navigate({pathname:location.pathname,search:params.toString()});}
  function move(delta:number){const nextIndex=cursor+delta;if(nextIndex<0||nextIndex>=trail.length)return;const next=trail[nextIndex];const params=new URLSearchParams(location.search);if(next===fallback)params.delete('section');else params.set('section',next);setCursor(nextIndex);setCurrent(next);localStorage.setItem(key,next);navigate({pathname:location.pathname,search:params.toString()},{replace:true});}
  return {current,select,back:()=>move(-1),forward:()=>move(1),canBack:cursor>0,canForward:cursor<trail.length-1};}

export function DashboardHistoryControls({back,forward,canBack,canForward}:{back:()=>void;forward:()=>void;canBack:boolean;canForward:boolean}){return <div className='flex items-center gap-1' aria-label='Dashboard section history'><Button type='button' size='icon' variant='outline' onClick={back} disabled={!canBack} aria-label='Previous dashboard section'><ArrowLeft className='size-4'/></Button><Button type='button' size='icon' variant='outline' onClick={forward} disabled={!canForward} aria-label='Next dashboard section'><ArrowRight className='size-4'/></Button></div>;}

function Message({ value }: { value: string }) { return value ? <p className='mt-4 text-sm' role='status'>{value}</p> : null; }
function Empty({ children }: { children: string }) { return <p className='rounded-sm border border-dashed border-primary/20 p-5 text-sm text-muted-foreground'>{children}</p>; }
function ActivationPending({ feature }: { feature: string }) { return <section className='paper-card p-6'><h2 className='font-serif text-3xl'>{feature}</h2><p className='mt-3 text-sm leading-6 text-muted-foreground'>Prepared and awaiting owner-approved Stage 4B database activation. Existing records remain available and no placeholder data is shown.</p></section>; } function HorseshoeIcon({ className }: { className?: string }) { return <svg aria-hidden='true' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round' className={className}><path d='M5 4v7a7 7 0 0 0 14 0V4h-4v7a3 3 0 0 1-6 0V4H5Z'/></svg>; }

function CourseSection() {
  const { profile } = useSession(); const refresh = useRefreshAcademy(); const stage4BReady=profile?.membership_tier!==undefined;
  const courses = useRows('hka_courses'); const enrolments = useRows('hka_enrolments'); const lessons = useRows('hka_lessons'); const progress = useRows('hka_progress'); const requests = useRows('hka_enrolment_requests');
  const [message, setMessage] = useState('');
  async function enrol(course: Row) { if (!profile) return; setMessage(''); try { if (course.access_level === 'free' && stage4BReady) { await rpc('hka_self_enrol_free', { target_course: course.id }); setMessage('Enrolment confirmed. Course is ready.'); } else { await saveRow('hka_enrolment_requests', { student_id: profile.id, course_id: course.id }); setMessage(course.access_level==='free'?'Enrolment request saved pending Stage 4B activation.':'Access request sent. Paid access remains locked until entitlement is verified.'); } refresh(); } catch (error) { setMessage(errorText(error)); } }
  const enrolled = new Set((enrolments.data ?? []).filter(row => row.status !== 'withdrawn').map(row => String(row.course_id))); const requested = new Set((requests.data ?? []).map(row => String(row.course_id))); const complete = new Set((progress.data ?? []).filter(row => row.completed_at).map(row => String(row.lesson_id)));
  return <div className='grid gap-6 xl:grid-cols-2'><section className='paper-card p-6'><div className='flex items-center justify-between gap-4'><h2 className='font-serif text-3xl'>My courses</h2><Link to='/learning-pathways' className='text-xs underline'>Browse pathways</Link></div><div className='mt-5 space-y-4'>{(enrolments.data ?? []).map(enrolment => { const course=(courses.data ?? []).find(row=>row.id===enrolment.course_id); const courseLessons=(lessons.data ?? []).filter(row=>row.course_id===enrolment.course_id && row.published); const count=courseLessons.filter(row=>complete.has(String(row.id))).length; const percent=courseLessons.length?Math.round(count/courseLessons.length*100):0; return <article key={enrolment.id} className='rounded-sm border border-primary/15 p-4'><h3 className='font-medium'>{String(course?.title ?? 'Enrolled course')}</h3><div className='mt-3 flex items-center gap-3'><Progress value={percent}/><span className='text-xs'>{percent}%</span></div><p className='mt-2 text-xs text-muted-foreground'>{count} of {courseLessons.length} lessons complete</p>{course && <Button asChild size='sm' className='mt-4'><Link to={'/academy/courses/'+course.id}>Continue course</Link></Button>}</article>; })}{!enrolments.isLoading && !enrolments.data?.length && <Empty>No current enrolments.</Empty>}</div></section>
    <section className='paper-card p-6'><h2 className='font-serif text-3xl'>Course catalogue</h2><p className='mt-2 text-sm text-muted-foreground'>Free courses open immediately. Basic and Premium courses require verified access.</p><div className='mt-5 space-y-3'>{(courses.data ?? []).filter(row=>row.published && !row.archived_at).map(course=><article key={course.id} className='rounded-sm border border-primary/15 p-4'><div className='flex items-start justify-between gap-3'><div><h3 className='font-medium'>{String(course.title)}</h3><p className='mt-1 text-xs text-muted-foreground'>{String(course.level)} · {String(course.access_level).toUpperCase()}</p></div>{enrolled.has(String(course.id))?<CheckCircle2 className='size-5 text-primary'/>:<Button size='sm' variant='outline' disabled={requested.has(String(course.id))} onClick={()=>void enrol(course)}>{requested.has(String(course.id))?'Requested':course.access_level==='free'?'Enrol':'Request access'}</Button>}</div></article>)}{!courses.isLoading && !courses.data?.length && <Empty>No published courses yet.</Empty>}</div><Message value={message}/></section></div>;
}

function CoachingSection() {
  const { profile }=useSession(); const refresh=useRefreshAcademy(); const stage4BReady=profile?.membership_tier!==undefined; const requests=useRows('hka_coaching_requests',{},stage4BReady); const appointments=useRows('hka_appointments'); const services=useRows('hka_coaching_services'); const [message,setMessage]=useState('');
  async function request(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!profile)return;const form=new FormData(event.currentTarget);setMessage('');try{await saveRow('hka_coaching_requests',{student_id:profile.id,service_id:form.get('service')||null,lesson_format:form.get('format'),preferred_starts_at:new Date(String(form.get('preferred'))).toISOString(),alternate_starts_at:form.get('alternate')?new Date(String(form.get('alternate'))).toISOString():null,duration_minutes:Number(form.get('duration')),learning_goals:form.get('goals'),location:form.get('location'),status:'pending'});event.currentTarget.reset();refresh();setMessage('Request sent for owner approval. This is not a confirmed booking.');}catch(error){setMessage(errorText(error));}}
  async function update(row:Row,action:'reschedule'|'cancel'){const status=action==='reschedule'?'reschedule_requested':row.status==='approved'?'cancellation_requested':'cancelled';try{await saveRow('hka_coaching_requests',{status,updated_at:new Date().toISOString()},String(row.id));refresh();setMessage(status==='cancelled'?'Request cancelled.':status==='cancellation_requested'?'Cancellation sent for owner approval.':'Rescheduling request sent for owner approval.');}catch(error){setMessage(errorText(error));}}
  if(!stage4BReady)return <ActivationPending feature='Coaching requests'/>;
  return <div className='grid gap-6 xl:grid-cols-[1fr_0.9fr]'><form className='paper-card grid gap-4 p-6' onSubmit={request}><h2 className='font-serif text-3xl'>Request coaching</h2><p className='text-sm text-muted-foreground'>Online and in-person coaching are separately priced. Owner approval is always required.</p><div><Label>Lesson type</Label><Select name='service'><SelectTrigger><SelectValue placeholder='Choose service'/></SelectTrigger><SelectContent>{(services.data??[]).filter(row=>row.active).map(row=><SelectItem key={row.id} value={String(row.id)}>{String(row.title)} · USD {String(row.price_usd)}</SelectItem>)}</SelectContent></Select></div><div className='grid gap-4 sm:grid-cols-2'><div><Label>Format</Label><Select name='format' defaultValue='online'><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value='online'>Online</SelectItem><SelectItem value='in_person'>In person</SelectItem></SelectContent></Select></div><div><Label htmlFor='coaching-duration'>Minutes</Label><Input id='coaching-duration' name='duration' type='number' min={30} max={240} defaultValue={60}/></div></div><div className='grid gap-4 sm:grid-cols-2'><div><Label htmlFor='preferred'>Preferred date and time</Label><Input id='preferred' name='preferred' type='datetime-local' required/></div><div><Label htmlFor='alternate'>Alternative date and time</Label><Input id='alternate' name='alternate' type='datetime-local'/></div></div><div><Label htmlFor='location'>Location or online preference</Label><Input id='location' name='location'/></div><div><Label htmlFor='goals'>Learning goals</Label><Textarea id='goals' name='goals' required className='min-h-28'/></div><Button className='w-fit'>Submit booking request</Button><Message value={message}/></form>
    <section className='paper-card p-6'><h2 className='font-serif text-3xl'>Schedule</h2><h3 className='mt-5 text-sm font-semibold'>Requests</h3><div className='mt-3 space-y-3'>{(requests.data??[]).map(row=><article key={row.id} className='rounded-sm border border-primary/15 p-4 text-sm'><strong className='capitalize'>{String(row.lesson_format).replace('_',' ')}</strong><p className='mt-1 text-xs text-muted-foreground'>{new Date(String(row.preferred_starts_at)).toLocaleString()} · {String(row.status)}</p>{row.owner_message&&<p className='mt-2'>{String(row.owner_message)}</p>}{['pending','alternative_proposed','approved'].includes(String(row.status))&&<div className='mt-3 flex gap-2'><Button size='sm' variant='outline' onClick={()=>void update(row,'reschedule')}>Request reschedule</Button><Button size='sm' variant='ghost' onClick={()=>void update(row,'cancel')}>{row.status==='approved'?'Request cancellation':'Cancel request'}</Button></div>}</article>)}{!requests.isLoading&&!requests.data?.length&&<Empty>No coaching requests.</Empty>}</div><h3 className='mt-6 text-sm font-semibold'>Confirmed lessons</h3><div className='mt-3 space-y-2'>{(appointments.data??[]).filter(row=>row.status==='scheduled').map(row=><p key={row.id} className='rounded-sm bg-primary/5 p-3 text-sm'>{String(row.title)} · {new Date(String(row.starts_at)).toLocaleString()}</p>)}{!appointments.data?.some(row=>row.status==='scheduled')&&<Empty>No upcoming confirmed lessons.</Empty>}</div></section></div>;
}

